def award_xp(correct):
    return 5 if correct else 0
print(award_xp(True))

def progress(done, total):
    if total <= 0:
        return 0
    return done / total * 100
print(progress(4, 10))

def label(course, level='Beginner'):
    return f'{course} · {level}'
print(label('Python'))
